<script>
(function(){
  // 1. Reading progress bar
  var pb=document.getElementById('nkpb');
  function updPb(){
    var sc=document.documentElement.scrollTop||document.body.scrollTop;
    var h=document.documentElement.scrollHeight-document.documentElement.clientHeight;
    if(pb) pb.style.width=(h>0?Math.round(sc/h*100):0)+'%';
  }
  window.addEventListener('scroll',updPb,{passive:true});

  // 2. Scroll reveal (IntersectionObserver)
  var ro=new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){e.target.classList.add('on');ro.unobserve(e.target);}
    });
  },{threshold:.12,rootMargin:'0px 0px -40px 0px'});
  document.querySelectorAll('.rev').forEach(function(el){ro.observe(el);});

  // 3. Flip cards
  document.querySelectorAll('.nk-flip').forEach(function(card){
    function toggle(){
      var on=card.classList.toggle('on');
      card.setAttribute('aria-pressed',on?'true':'false');
    }
    card.addEventListener('click',toggle);
    card.addEventListener('keydown',function(e){
      if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}
    });
  });

  // 4. FAQ accordion
  document.querySelectorAll('.nk-fq').forEach(function(btn){
    btn.addEventListener('click',function(){
      var exp=this.getAttribute('aria-expanded')==='true';
      // close all
      document.querySelectorAll('.nk-fq').forEach(function(b){
        b.setAttribute('aria-expanded','false');
        var ans=document.getElementById(b.getAttribute('aria-controls'));
        if(ans) ans.style.maxHeight='0';
      });
      if(!exp){
        this.setAttribute('aria-expanded','true');
        var ans=document.getElementById(this.getAttribute('aria-controls'));
        if(ans) ans.style.maxHeight=ans.scrollHeight+'px';
      }
    });
  });

  // 5. Checklist counter
  var cbs=document.querySelectorAll('.nk-ck__cb');
  var countEl=document.getElementById('nkCkCount');
  var msgLo=document.getElementById('nkMsgLo');
  var msgMi=document.getElementById('nkMsgMi');
  var msgHi=document.getElementById('nkMsgHi');
  function updCk(){
    var n=document.querySelectorAll('.nk-ck__cb:checked').length;
    if(countEl) countEl.textContent=n;
    if(msgLo) msgLo.classList.toggle('show',n>=1&&n<=2);
    if(msgMi) msgMi.classList.toggle('show',n>=3&&n<=4);
    if(msgHi) msgHi.classList.toggle('show',n>=5);
  }
  cbs.forEach(function(cb){cb.addEventListener('change',updCk);});
})();
</script>

